import{_ as a,o as l,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Orchestrator Meeting: 2021-12-07","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting: 2021-12-07","date":"2021-12-07T00:00:00.000Z","updated":"2021-12-11T00:00:00.000Z","tags":["Ceph","分布式存储","Kubernetes","性能优化","自动化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_-_2021-12-07.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_-_2021-12-07.md","lastUpdated":1780460162000}'),i={name:"posts/2021/Ceph_Orchestrator_Meeting_-_2021-12-07.md"};function o(n,e,s,h,p,u){return l(),t("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要-ceph-orchestrator-周会" tabindex="-1">会议纪要：Ceph Orchestrator 周会 <a class="header-anchor" href="#会议纪要-ceph-orchestrator-周会" aria-label="Permalink to &quot;会议纪要：Ceph Orchestrator 周会&quot;">​</a></h3><h4 id="会议时间-2021-12-07" tabindex="-1">会议时间：2021-12-07 <a class="header-anchor" href="#会议时间-2021-12-07" aria-label="Permalink to &quot;会议时间：2021-12-07&quot;">​</a></h4><h4 id="参会人员-列出主要参会人员" tabindex="-1">参会人员：[列出主要参会人员] <a class="header-anchor" href="#参会人员-列出主要参会人员" aria-label="Permalink to &quot;参会人员：[列出主要参会人员]&quot;">​</a></h4><h4 id="会议议程" tabindex="-1">会议议程： <a class="header-anchor" href="#会议议程" aria-label="Permalink to &quot;会议议程：&quot;">​</a></h4><ol><li>Rook 团队更新</li><li>TopoLVM 新 Operator 开发进展</li><li>大规模集群测试反馈</li><li>Kubernetes 与 Ceph 的集成问题讨论</li><li>维护模式与离线主机处理</li><li>Agent 与 Manager 的通信优化</li></ol><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>Rook 团队更新</strong></p><ul><li>Rook 团队未参会，无更新内容。</li></ul></li><li><p><strong>TopoLVM 新 Operator 开发进展</strong></p><ul><li>决定开发全新的 TopoLVM Operator，以满足新的需求。</li><li>新 Operator 将从零开始，计划几周内提交设计方案。</li><li>目前工作重点是实现单节点部署和设备选择等基本功能。</li></ul></li><li><p><strong>大规模集群测试反馈</strong></p><ul><li>讨论了在大型集群中的性能和稳定性问题，特别是节点离线情况。</li><li>强调了需要对集群进行压力测试，并优化 Prometheus 监控模块。</li></ul></li><li><p><strong>Kubernetes 与 Ceph 的集成问题讨论</strong></p><ul><li>讨论了 Kubernetes 如何处理离线节点，并提出了借鉴其方法的建议。</li><li>提出了在 Ceph 中实现类似 Kubernetes 的节点故障检测和自动重调度机制。</li></ul></li><li><p><strong>维护模式与离线主机处理</strong></p><ul><li>讨论了维护模式与离线状态的处理逻辑，建议简化并统一处理方式。</li><li>提出了在维护模式下快速重调度无状态服务的建议。</li></ul></li><li><p><strong>Agent 与 Manager 的通信优化</strong></p><ul><li>讨论了 Agent 如何快速发现新的 Active Manager 的问题。</li><li>提出了通过改进 Agent 的配置更新机制来加速这一过程的建议。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>开发全新的 TopoLVM Operator，并计划在几周内提交设计方案。</li><li>对大型集群进行压力测试，特别是关注节点离线时的系统行为。</li><li>研究并借鉴 Kubernetes 的节点故障处理机制，改进 Ceph 的相应功能。</li><li>优化 Agent 与 Manager 的通信机制，减少 Manager 切换时的延迟。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续开发 TopoLVM 新 Operator，并定期更新开发进度。</li><li>实施并验证大型集群的压力测试方案。</li><li>分析 Kubernetes 的节点故障处理机制，提出并实施改进方案。</li><li>优化 Agent 的配置更新机制，减少 Manager 切换时的通信延迟。</li></ul><h4 id="下次会议预告" tabindex="-1">下次会议预告： <a class="header-anchor" href="#下次会议预告" aria-label="Permalink to &quot;下次会议预告：&quot;">​</a></h4><ul><li>下次会议将在下周同一时间进行，届时将讨论上述行动计划的进展情况。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><ul><li>会议在参会人员的积极讨论中圆满结束，期待下次会议的进一步成果。</li></ul><p><strong>备注：</strong> 本次会议记录涵盖了关键的技术讨论和决策，为后续的开发和测试工作提供了明确的方向和行动计划。</p>',16)])])}const _=a(i,[["render",o]]);export{d as __pageData,_ as default};
